    out = []
    for idx, row in enumerate(vectors):
        if 'edge' in row:
            e = row['edge']
            if isinstance(e, str):
                pos = 'pos' in e.lower()
            else:
                pos = (e == 1 or e is True)
        elif 'clk_in' in row:
            pos = (row['clk_in'] == 1)
        else:
            pos = (idx % 2 == 0)

